\addplot[thick,red!70!black,dashdotted,<->,domain=0.421875:2.37037037,samples=150] {ln(x)/ln(3/4)};
\node[blue!70!black,fill=white,inner sep=1pt] at (axis cs:1.7,2.7) {$y=\log_{4/3}x$};
\node[red!70!black,fill=white,inner sep=1pt] at (axis cs:1.7,-2.7) {$y=\log_{3/4}x$};
